using GastricCancerDetection.Infrastructure.Persistence; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace GastricCancerDetection.Api.Controllers; [ApiController][Route("api/cnv")] public class CnvController:ControllerBase { private readonly GastricCancerDbContext _db; public CnvController(GastricCancerDbContext db)=>_db=db; [HttpGet] public async Task<IActionResult> Get([FromQuery]int? runId=null,[FromQuery]string? eventType=null){var q=_db.CopyNumberAlterations.AsNoTracking();if(runId.HasValue)q=q.Where(x=>x.AnalysisRunId==runId);if(!string.IsNullOrWhiteSpace(eventType))q=q.Where(x=>x.EventType==eventType);return Ok(await q.OrderByDescending(x=>x.TumorFrequency).Take(1000).ToListAsync());} }
